function [on] = valve_on_time(duty, t, mib, res)
%VALVE_ON_TIME  The valve's on-time [s] in a period t [s] for the duty (0 to 1): clamped, under mib none, rounded to res.
%   duty: real[1] (passed a plain number)
%   t: real[s] (passed in s)
%   mib: real[s] (passed in s)
%   res: real[s] (passed in s)
%   returns on: real[s] (passed in s)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    on = 0;
    x = (asils.models.coilsat.act_clamp(duty, 0, 1) * t);
    if (x < mib)
        x = 0;
    end
    on = (round((x / res)) * res);
end
